def _reset_validation_session_state():
    for key in _validation_session_keys():
        default = DEFAULT_STATE.get(
            key
        )

        st.session_state[key] = (
            default.copy()
            if isinstance(
                default,
                set,
            )
            else default
        )


def _normalise_validation_value(
    field,
    value,
):
    if value is None:
        return ""

    value = " ".join(
        str(value)
        .strip()
        .split()
    )

    if field in {
        "nafdac_number",
        "batch_number",
    }:
        return value.upper()

    return value.casefold()


def _count_user_corrections(
    original,
    confirmed,
):
    original = original or {}
    confirmed = confirmed or {}

    count = 0

    for field in [
        "product_name",
        "nafdac_number",
        "manufacturer",
        "batch_number",
        "expiry_date",
    ]:
        before = _normalise_validation_value(
            field,
            original.get(
                field
            ),
        )

        after = _normalise_validation_value(
            field,
            confirmed.get(
                field
            ),
        )

        if before != after:
            count += 1

    return count


def _begin_validation_session_if_needed():
    """
    Create one Supabase validation session for this product check.

    Failure never blocks the product-safety flow. It is surfaced to
    the tester so an unlogged interaction is not mistaken for a
    documented validation interaction.
    """

    if st.session_state.validation_session_id:
        return True

    participant_id = (
        st.session_state.validation_participant_id
    )

    if not participant_id:
        st.session_state.validation_error = (
            "Validation logging is not active for this interaction."
        )
        return False

    try:
        session = start_validation_session(
            participant_id=participant_id,
            language=selected_language_name(),
            input_method="voice",
            product_type=None,
            voice_replies_enabled=bool(
                st.session_state.get(
                    "voice_replies_enabled",
                    False,
                )
            ),
            app_version="naic-2026-validation-v1",
            validation_environment=(
                "real_user_test"
                if st.session_state.validation_validator_type
                == "external_user"
                else "internal_test"
            ),
        )

        st.session_state.validation_session_id = (
            session.get(
                "id"
            )
        )

        st.session_state.validation_test_id = (
            session.get(
                "test_id"
            )
        )

        st.session_state.validation_started_at_epoch = (
            time.time()
        )

        st.session_state.validation_error = None

        return True

    except Exception as error:
        st.session_state.validation_error = (
            "Validation logging could not start: "
            f"{type(error).__name__}: {error}"
        )

        return False


def _save_validation_result_if_needed(
    product,
    result,
):
    if st.session_state.validation_check_saved:
        return

    session_id = (
        st.session_state.validation_session_id
    )

    if not session_id:
        return

    try:
        save_validation_check(
            session_id=session_id,
            product_state=(
                product
                or {}
            ),
            evidence_result=(
                result
                or {}
            ),
            asr_success=(
                st.session_state.validation_asr_success
            ),
            extraction_success=(
                st.session_state.validation_extraction_success
            ),
            corrections_needed=(
                st.session_state.validation_corrections_needed
            ),
            correction_count=(
                st.session_state.validation_correction_count
            ),
            interpreter_used=(
                st.session_state.interpreter_used
            ),
        )

        st.session_state.validation_check_saved = True

        if not st.session_state.validation_session_completed:
            started = (
                st.session_state.validation_started_at_epoch
            )

            duration_seconds = None

            if started is not None:
                duration_seconds = max(
                    0,
                    int(
                        time.time()
                        - started
                    ),
                )

            complete_validation_session(
                session_id=session_id,
                task_completed=True,
                duration_seconds=duration_seconds,
            )

            st.session_state.validation_session_completed = True

        st.session_state.validation_error = None

    except Exception as error:
        st.session_state.validation_error = (
            "The product check completed, but the validation record "
            "could not be saved: "
            f"{type(error).__name__}: {error}"
        )


def _render_validation_status():
    if st.session_state.validation_test_id:
        st.caption(
            "Anonymous validation ID: "
            f"{st.session_state.validation_test_id}"
        )

    if st.session_state.validation_error:
        st.warning(
            st.session_state.validation_error
        )


def reset_check():
    current_language = (
        selected_language()
    )

    keys = [
        "transcript",
        "extracted_details",
        "product_state",
        "followup_transcript",
        "followup_field",
        "product_name_input",
        "nafdac_number_input",
        "manufacturer_input",
        "batch_number_input",
        "expiry_date_input",
        "initial_audio",
        "interpreter_used",
        "interpreter_error",
        "evidence_result",
        "last_asr_seconds",
        "last_gemini_seconds",
    ]

    for key in keys:
        st.session_state.pop(
            key,
            None,
        )

    for key in list(
        st.session_state.keys()
    ):
        if (
            key.startswith(
                "answer_"
            )
            or
            key.startswith(
                "audio_"
            )
        ):
            del st.session_state[
                key
            ]

    for key, value in DEFAULT_STATE.items():
        if key.startswith(
            "pharmacy_"
        ):
            continue

        if key == "selected_language":
            continue

        if key in _validation_participant_keys():
            continue

        st.session_state[key] = (
            value.copy()
            if isinstance(
                value,
                set,
            )
            else value
        )

    st.session_state.selected_language = (
        current_language
    )


def restart_product_capture():
    """
    Record the same validation interaction again.

    Product-capture state is cleared, while an already-created
    validation session is preserved so a re-recording does not
    become a fake second interaction.
    """
    preserved_validation = {
        key: st.session_state.get(
            key
        )
        for key in _validation_session_keys()
    }

    reset_check()

    for key, value in preserved_validation.items():
        st.session_state[key] = value

    st.session_state.current_step = (
        "capture"
    )


def start_another_product_check():
    """Start a genuinely new validation interaction."""
    reset_check()
    _reset_validation_session_state()

    st.session_state.current_step = (
        "capture"
    )


