def render_progress(
    active_step,
):
    """
    The product-check journey is intentionally shown as only two
    user-facing steps:

    1. Tell + confirm
    2. Evidence

    Internal work can still happen inside either step without making
    the user move through extra screens.
    """
    steps = [
        (
            "capture",
            "Tell + confirm",
        ),
        (
            "result",
            "Evidence",
        ),
    ]

    order = {
        name: index
        for index, (
            name,
            _,
        ) in enumerate(
            steps
        )
    }

    active_index = order.get(
        active_step,
        0,
    )

    markup = (
        '<div class="progress-wrap">'
    )

    for index, (
        _,
        label,
    ) in enumerate(
        steps
    ):
        class_name = (
            "progress-step"
        )

        if index < active_index:
            class_name += (
                " done"
            )

        if index == active_index:
            class_name += (
                " active"
            )

        markup += (
            f'<div class="{class_name}">'
            f'<span class="progress-num">{index + 1}</span>'
            f'<span class="progress-label">{label}</span>'
            '</div>'
        )

    markup += (
        "</div>"
    )

    render_html(
        markup
    )


