def format_watch_time(
    value,
):
    if not value:
        return (
            "Not checked yet"
        )

    try:
        parsed = datetime.fromisoformat(
            value.replace(
                "Z",
                "+00:00",
            )
        )

        return parsed.strftime(
            "%d %b %Y, %H:%M UTC"
        )

    except ValueError:
        return str(
            value
        )


def render_watch_status(
    result,
):
    if not result:
        st.info(
            "This product has not "
            "been re-checked yet."
        )

        return

    code = result.get(
        "code"
    )

    headline = result.get(
        "headline",
        "Evidence check complete",
    )

    if code == "safety_alert_match":
        st.error(
            f"⚠ {headline}"
        )

    elif code == "international_alert_relevant":
        st.warning(
            f"⚠ {headline}"
        )

    elif code == "current_record_match":
        st.success(
            "✓ No matching high-priority "
            "safety alert found in the "
            "connected sources."
        )

    elif code == "historical_record_found":
        st.info(
            "No matching high-priority "
            "safety alert found. "
            "Current registration status "
            "is still not confirmed."
        )

    else:
        st.info(
            headline
        )


def distance_label(
    metres,
):
    if metres is None:
        return None

    metres = int(
        metres
    )

    if metres < 1000:
        return (
            f"{metres} m "
            "from the search centre"
        )

    return (
        f"{metres / 1000:.1f} km "
        "from the search centre"
    )


def pharmacy_voice_summary(
    records,
    location_name,
):
    count = len(
        records
    )

    if count == 0:
        return (
            "I did not find a usable pharmacy "
            f"location near {location_name} "
            "in the current search. "
            "You can change the area "
            "or radius and try again."
        )

    return (
        f"I found {count} pharmacy "
        f"location{'s' if count != 1 else ''} "
        f"near {location_name}. "
        "I cleaned and ranked the discovery results, "
        "but Pharmacy Council of Nigeria verification "
        "is still separate."
    )


